aside {
  padding: 8px 10px
}

::v-deep .el-tree-node {
  width: 300px;
}

::v-deep .el-tree-node__expand-icon.is-leaf {
  width: 13px;
}

.el-col-8 {
  height: 30px;
}

.ippool {
  color: #606266;
  font-size: 14px
}

ul {
  list-style: none;
}

.content {
  display: flex;

}

.ip_info {
  width: 22%;
  height: 100%;
  overflow: auto;
}

.ip_box {
  flex: 1;
}

.ip_box ul {
  width: 100%;
  display: flex;
  flex-wrap: wrap;
  padding: 0px;
  margin: 0px;
  justify-content: space-between
}

.ip_box ul li {
  width: 5.5%;
  text-align: center;
  /* border: 1px solid #00a9b8; */
  height: 3vh;
  line-height: 3vh;
  margin-bottom: 0.6%;
  margin-right: 0.5%;
  font-size: 0.8rem;
  border-radius: 3px;
  color: #fff;
  cursor: pointer;
  // background: url('../../../assets/styles/按钮.png') no-repeat;
  background: #a1a1a1;
  background-size: 100% 100%;
  // overflow: hidden;
  /* border: 1px solid #606266 */
}

// .ip_box ul li >span{
//   display: block;
// }
.tip {
  text-align: center;
  font-size: 0.8rem;
  margin: 15px 0;
}

.tip span {
  display: inline-block;
  width: 14%;
  height: 1.3rem;
  line-height: 1.3rem;
  text-align: center
}

.tip span i {
  display: inline-block;
  width: 2rem;
  vertical-align: top;
  height: 90%;
  margin-right: 5px;
  border-radius: 3px;
}

.ip_box ul .is_use {
  // background: url('../../../assets/styles/按钮1.png') no-repeat;
  background: rgb(92, 219, 211);
  background-size: 100% 100%;
  color: #fff;
  border: none;
}

.ip_box ul .wangguan {
  // background: yellow;
  background: rgb(24, 144, 255);
  border: none;
}

.i_default {
  background: #82848a;
  border: none;
}

.online {
  color: #fff !important;
}

.offline {
  color: #606266 !important;
}

.ip_box ul .is_range {
  // background: url('../../../assets/styles/按钮2.png') no-repeat;
  background: rgb(105, 192, 255);
  color: #fff;
  border: none;
}

.nouse_online {
  color: red !important;
}

.ip_box ul .is_normel {
  // background: url('../../../assets/styles/按钮2.png') no-repeat;
  background: rgb(105, 192, 255);
  background-size: 100% 100%;
  color: #ff4040;
  font-weight: bold;
  border: none;
}

.form-page .el-col-6 {
  height: 40px;
}

.ip_info .el-row {
  border: 1px solid #dcdfe6;
  text-align: center;
  height: 2rem;
  line-height: 2rem
}

.ip_info .el-col {
  border-right: 1px solid #dcdfe6;
  height: 2rem;
  line-height: 2rem;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  margin-bottom: 0;
}

.el-row .switch {
  cursor: pointer;
  color: #47aa9a
}

::v-deep .el-switch__label * {
  font-size: 0.4rem;
}

.switch_box {
  background: url('../../assets/workflow/switch.png');
  background-size: 100% 100%;
  min-height: 60vh;
  position: relative;
}

.postion_box {
  width: 50%;
  position: absolute;
  left: 31%;
  top: 50%
}

.switch_box ul {

  padding: 0;
  display: flex;
  height: 15vh;
  flex-direction: column;
  flex-wrap: wrap;
  width: 100%;
  align-items: center;
}

.switch_box ul li {
  display: flex;
  flex-direction: column;
  width: 4.2%;
  /* margin-right: 2%; */
  flex-direction: column-reverse;
  align-items: center;
  color: #fff;
  font-size: 12px
}

.switch_box ul li .item_back {
  width: 100%;
  height: 2.5vh;
  /* background: #000; */
}

.switch_box ul li .no_range {
  // background: url('../../../assets/styles/7.png') no-repeat;
  background-size: 100% 100%;
}

.switch_box ul li .is_range {
  // background: url('../../../assets/styles/无标题.png') no-repeat;
  background-size: 100% 100%;
}

.switch_box ul li .is_use {
  // background: url('../../../assets/styles/6.png') no-repeat;
  background-size: 100% 100%;
}

.btn2 {
  // background: url('../../../assets/styles/按钮2.png') no-repeat;
  background: rgb(105, 192, 255);
  background-size: 100% 100%;
}

.btn3 { // 已分配
  // background: url('../../../assets/styles/按钮1.png') no-repeat;
  background: rgb(92, 219, 211);
  background-size: 100% 100%;
}

.btn5 { // 异常
  background: rgb(181, 245, 236);
  background-size: 100% 100%;
}

.btn4 {
  // background: yellow;
  background: rgb(24, 144, 255);
}


.switch_tips {
  text-align: center
}

.switch_tips span {
  display: inline-block;
  margin: 0 1.5vw
}

.switch_tips span i {
  display: inline-block;
  width: 3vw;
  height: 2.8vh;
  /* background: #47aa9a; */
  vertical-align: text-bottom;
}


.arrow_box {
  color: #00ff00 !important;
}

